"""Fiscal-only bridge from merged PR #26; never changes adopted inputs.
Run after common rebuild. --write publishes the comparison, not a selected baseline.
"""
import argparse, hashlib, importlib.util, json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
spec=importlib.util.spec_from_file_location('recovery',ROOT/'index/tools/recovery-budget/model.py')
m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
SOURCE=ROOT/'sources/climate-portfolio-pricing.json'

def adjustments(budget, case, inflation, ramp):
    gf=dict(budget['results'][case]['general_fund_path_bn'])
    # Climate model ends in 2050: hold its net GF obligation constant in real terms.
    for y in range(2051,2057): gf[str(y)]=gf['2050']*(1+inflation)**(y-2050)
    # The report exports capital totals, not annual component paths. Preserve its
    # documented grid equal-real profile and disaster 50/75/100 ramp, normalized
    # to the exact exported nominal window costs. No second $195B surge saving.
    capital={str(y):0.0 for y in m.Y}
    for item in budget['items']:
        if item['account']!='D4-B borrowing': continue
        weights={y:(1+inflation)**(y-2025)*( ramp.get(str(y),1) if item['id']=='disaster_cap' else 1) for y in m.W}
        for y,w in weights.items(): capital[str(y)]+=item['window_bn'][case]*w/sum(weights.values())
    return {'PR26 general-fund net obligation':{'annual_bn':gf},
            'PR26 finite capital deficit cost':{'annual_bn':capital}}

def build():
    budget=json.loads(SOURCE.read_text())['budget']
    pricing=json.loads((ROOT/'index/tools/climate-portfolio/pricing.json').read_text())
    inflation=pricing['inflation']
    f,b,old,u=m.load();results=[]
    for financing,high in [('existing_reforms',0),('upper_income_comparator',4)]:
        for case in ['capacity_reference','central','conservative','unfavorable']:
            adj={} if case=='capacity_reference' else adjustments(budget,case,inflation,pricing['disaster']['ramp'])
            c=m.build_case(case,f,b,old,u,high_rate=high,broad_rate=0,corridor=True,spending_adjustments=adj)
            results.append(dict(financing=financing,case=case,summary=c['summary'],
                delta_2030_39_bn=sum(v['annual_bn'].get(str(y),0) for v in adj.values() for y in m.W),
                delta_2040_bn=sum(v['annual_bn'].get('2040',0) for v in adj.values()),
                delta_2050_bn=sum(v['annual_bn'].get('2050',0) for v in adj.values())))
    return dict(source_sha256=hashlib.sha256(SOURCE.read_bytes()).hexdigest(),source_main='79b89d5f43a3a9a00f076faa148ea3098711422c',
        pricing_sha256=hashlib.sha256((ROOT/'index/tools/climate-portfolio/pricing.json').read_bytes()).hexdigest(),
        status='Exploratory net fiscal bridge; not the fully integrated climate baseline or D3/D4 certification',
        inflation=inflation,results=results)

def report(d):
    lines=['# Climate package and the recovery financing envelope','',
      'Generated by `index/tools/financing-protection/climate_bridge.py`. This supersedes the provisional climate ceilings in [the historical spending comparison](spending-package-comparisons.md). Source: merged PR #26 on main `79b89d5`; [component costs and financing](climate-portfolio-pricing.md). No new tax or spending decision is adopted here.','',
      'The climate redesign is a substantive investment, not a free source of permanent savings. Its credit savings expire while disaster protection and the carbon-related income/payroll tax offset continue. Use the conservative savings case for financing until scored; keep the central case as a comparison. Preserve housing and participation while reconciling credible additional progressive revenues.','',
      '| Climate case | Added primary cost, 2030–39 | FY2040 | FY2050 | Debt/GDP 2056, existing reforms | Upper-income comparator |',
      '| --- | ---: | ---: | ---: | ---: | ---: |']
    for case in ['capacity_reference','central','conservative','unfavorable']:
        rows=[r for r in d['results'] if r['case']==case];a,b=rows
        lines.append(f"| {case} | ${a['delta_2030_39_bn']:.1f}B | ${a['delta_2040_bn']:.1f}B | ${a['delta_2050_bn']:.1f}B | {a['summary']['debt_gdp_2056']:.1f}% | {b['summary']['debt_gdp_2056']:.1f}% |")
    passes=[r['case']+'/'+r['financing'] for r in d['results'] if r['summary']['debt_ratio_nonincreasing_2045_56']]
    lines+=['', 'Debt nonincreasing throughout 2045–56: '+(', '.join(passes) if passes else '**none of these cases**')+'.','',
      '## Accounting and limits','',
      '- Uses PR #26’s exported annual general-fund net path through 2050, including CX and carbon-channel shortfalls. Adds finite grid/disaster capital deficit costs once. The $195B capacity-surge reduction is already in the reference and is never deducted again.',
      '- D7 remains 80% dividend / 20% transition. Unused transition receipts remain reserved for that channel; they are not swept into the general fund. This uses the same fully committed channel convention as the recovery reference, rather than claiming its surplus as a new debt saving.',
      '- General-fund net costs are represented as outlay-equivalent adjustments solely to compute deficits and debt. These scenario revenue/outlay totals are not a gross carbon-account crosswalk. The underlying recovery reference and household diagnostic still use the historical carbon schedule. Neither is a complete post-PR #26 baseline.',
      '- Annual capital timing reconstructs the documented equal-real grid profile and disaster ramp, normalized to exact exported window totals. After 2050, net general-fund cost grows with the pricing model’s inflation assumption; this is an explicit extrapolation, not modeled emissions or receipts. Loan principal financing, repayments and financial assets need a separate public-debt financing crosswalk beyond deficit-cost scoring.',
      '- Existing reforms and the four-point upper-income comparator retain the same illustrative education/SS rates and $300 credit as the earlier comparison. The latter is not a wealthy-only tax. Climate cost cases are not comprehensive macro downside cases or probability forecasts.',
      '- No additional CLI-13 removal purchases or federal reinsurance backstop are counted. Both remain separate decisions. No avoided-disaster losses or dynamic growth receipts are banked.',
      '', '## Final review boundary and next assignment','',
      'PR #24 integrates the approved capacity and fund-administration decisions and provides this financing comparison. It does not settle the climate general-fund pay-for or certify household protection. Final review should verify capacity costs are charged once, the education current-law identity, fund sensitivities, and this bridge’s annual accounting.',
      '', 'The next numerical integration must replace the historical carbon, revenue and incidence paths together with the approved $150-by-2037 price and Package A, reconcile credit rows across CLI-1/CLI-5, and expose borrowing versus loan-financing needs. Finance the conservative recurring obligation through the revenue settlement; any change to D7’s dividend split remains Espen’s decision. Do not stack the old $200B/$305B exploratory savings onto this package.','']
    return '\n'.join(lines)

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--write',action='store_true');args=p.parse_args();d=build()
    if args.write:
        (ROOT/'sources/climate-recovery-financing-comparison.json').write_text(json.dumps(d,indent=2)+'\n')
        (ROOT/'sources/climate-recovery-financing-comparison.md').write_text(report(d))
    else: print(report(d))
